    // [WSCoop] Per-player gathering: the gatherer's own game plays the usual pickup feedback and hides the
    // node for them until it regrows for them; the server keeps it up for everyone else.
    void WSCoopPlayLocalPickup()
    {
        if (PickupSound != nullptr)
        {
            AkGameplay::PostEvent(PickupSound, this, 0);
        }
        UNiagaraSystem PickupEffect = UInventorySettings::GetItemPickupEffect();
        if (PickupEffect != nullptr)
        {
            Niagara::SpawnSystemAtLocation(PickupEffect, ActorLocation, ActorRotation);
        }
    }

